def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform separator line with cells on both sides.
    candidates = []
    for r, row in enumerate(grid):
        if 0 < r < h - 1 and len(set(row)) == 1:
            candidates.append((r, True))
    for c in range(w):
        if 0 < c < w - 1 and len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((c, False))

    # The separator is the uniform line separating two equal-sized panels.
    sep, horizontal = min(
        candidates,
        key=lambda item: abs(
            (item[0] if item[1] else item[0]) -
            ((h if item[1] else w) / 2)
        )
    )

    if horizontal:
        first = grid[:sep]
        second = grid[sep + 1:]
    else:
        first = [row[:sep] for row in grid]
        second = [row[sep + 1:] for row in grid]

    # One panel is a mostly-filled mask with zero holes; the other is the
    # binary pattern. Keep pattern cells only where the mask is filled.
    def zero_count(panel):
        return sum(v == 0 for row in panel for v in row)

    mask, pattern = (first, second) if zero_count(first) < zero_count(second) else (second, first)

    return [
        [2 if mask[r][c] != 0 and pattern[r][c] != 0 else 0
         for c in range(len(mask[0]))]
        for r in range(len(mask))
    ]
